class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:

        return [self.first_binary_search(0, len(nums)-1, nums, target), self.last_binary_search(0, len(nums)-1, nums, target)]

    def first_binary_search(self, start, end, nums, target):
        while start <= end:
            mid = (start+end)//2
            mid_number = nums[mid]
            if mid_number == target and mid>0 and target==nums[mid-1] or mid_number > target:
                end = mid-1
            elif mid_number<target:
                start = mid + 1
            else:
                return mid
        return -1

    def last_binary_search(self, start, end, nums, target):
        while start <= end:
            mid = (start+end)//2
            mid_number = nums[mid]
            if mid_number==target and mid<end and target==nums[mid+1]or mid_number < target:
                start=mid+1
            elif mid_number > target:
                end=mid-1
            else:
                return mid
        return -1

