def check_negative_cycle(
    graph: list[dict[str, int]], distance: list[float], edge_count: int
) -> bool:
    for j in range(edge_count):
        u, v, w = (graph[j][k] for k in ["src", "dst", "weight"])
        if distance[u] != float("inf") and distance[u] + w < distance[v]:
            return True
    return False


