def find_pattern(pattern: str, text: str) -> int:
    """
    Uses the Rabin-Karp algorithm to find the first occurrence of the pattern in the text.
    Returns the starting index of the first occurrence if found, otherwise returns -1.
    """
    # Base parameters for the Rabin-Karp algorithm
    base = 256
    prime = 101

    m = len(pattern)
    n = len(text)

    # Early exit if pattern length is greater than text length
    if m > n:
        return -1

    # Compute the hash value for the pattern and the first window of the text
    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(m-1):
        h = (h * base) % prime

    for i in range(m):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(n - m + 1):
        if pattern_hash == text_hash:
            # Verify the characters if hash matches
            for j in range(m):
                if text[i + j] != pattern[j]:
                    break
            else:
                return i

        if i < n - m:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + m])) % prime
            if text_hash < 0:
                text_hash += prime

    return -1

