def bellman_ford(graph, source):
    """
    Implements the Bellman-Ford algorithm to detect negative-weight cycles
    in a graph and find the shortest path from a source node.

    Parameters:
    graph (dict): A dictionary representing the directed graph, with edge weights.
    source (str): The starting node.

    Returns:
    bool: True if no negative-weight cycles exist, False otherwise.
    """

    # Initialize distance to all vertices as infinite and distance to source as 0
    distance = {node: float('inf') for node in graph}
    distance[source] = 0

    # Relax edges |V|-1 times
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if distance[u] != float('inf') and distance[u] + graph[u][v] < distance[v]:
                    distance[v] = distance[u] + graph[u][v]

    # Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if distance[u] != float('inf') and distance[u] + graph[u][v] < distance[v]:
                return False  # Negative cycle detected

    return True

def rabin_karp(word: str, text: str) -> int:
    if not word or not text or len(word) > len(text):
        return -1

    base = 256
    prime = 101
    m = len(word)
    n = len(text)

    hash_word = 0
    hash_text = 0
    h = 1

    for i in range(m - 1):
        h = (h * base) % prime

    for i in range(m):
        hash_word = (base * hash_word + ord(word[i])) % prime
        hash_text = (base * hash_text + ord(text[i])) % prime

    for i in range(n - m + 1):
        if hash_word == hash_text:
            if text[i:i + m] == word:
                return i

        if i < n - m:
            hash_text = (base * (hash_text - ord(text[i]) * h) + ord(text[i + m])) % prime
            if hash_text < 0:
                hash_text = hash_text + prime

    return -1

def rabin_karp_enhanced(pattern: str, text: str) -> int:
    """
    Finds the first occurrence of the pattern in the text using the Rabin-Karp algorithm.
    :param pattern: The substring to be searched.
    :param text: The text within which the pattern is to be searched.
    :return: The starting index of the first occurrence of the pattern in the text, or -1 if the pattern is not found.
    """
    if len(pattern) > len(text):
        return -1

    base = 256  # Number of characters in the input alphabet
    prime = 101  # A prime number to use for hashing

    pattern_length = len(pattern)
    text_length = len(text)

    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(pattern_length - 1):
        h = (h * base) % prime

    for i in range(pattern_length):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(text_length - pattern_length + 1):
        if pattern_hash == text_hash:
            if text[i:i + pattern_length] == pattern:
                return i

        if i < text_length - pattern_length:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + pattern_length])) % prime

            if text_hash < 0:
                text_hash += prime

    return -1

from collections import deque

def shortest_path(graph, start, end):
    """
    Find the shortest path between start and end nodes in an unweighted graph.
    """
    if start not in graph or end not in graph:
        return []

    queue = deque([start])
    predecessors = {start: None}

    while queue:
        current = queue.popleft()
        if current == end:
            break
        for neighbor in graph[current]:
            if neighbor not in predecessors:
                queue.append(neighbor)
                predecessors[neighbor] = current

    if end not in predecessors:
        return []

    path = []
    curr_node = end
    while curr_node is not None:
        path.append(curr_node)
        curr_node = predecessors[curr_node]
    path.reverse()

    return path

