def find_pair_with_sum(nums: List[int], target: int) -> Optional[Tuple[int, int]]:
    """
    Finds the indices of the two numbers in the array that add up to the target integer.
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], i)
        num_to_index[num] = i

    return None  # In case no valid pair is found, although the prompt guarantees one solution

