def countLessThanMid ( mid , N , M , K ) :
    count = 0
    for i in range ( 1 , min ( N , mid ) + 1 ) :
        count = count + min ( mid // i , M )
    if ( count >= K ) :
        return False
    else :
        return True
def findKthElement ( N , M , K ) :
    low = 1
    high = N * M
    while ( low <= high ) :
        mid = low + ( high - low ) // 2
        if ( countLessThanMid ( mid , N , M , K ) ) :
            low = mid + 1
        else :
            high = mid - 1
    return high + 1
