def insert ( node , key ) :
    if ( node == None ) :
        return newNode ( key )
    if ( key < node . key ) :
        node . left = insert ( node . left , key )
    elif ( key > node . key ) :
        node . right = insert ( node . right , key )
    return node
def KSmallestPerfectBST ( root , k , treeSize ) :
    global kth_smallest
    if ( root == None ) :
        return False
    median_loc = ( treeSize // 2 ) + 1
    if ( k == median_loc ) :
        kth_smallest = root . key
        return True
    newTreeSize = treeSize // 2
    if ( k < median_loc ) :
        return KSmallestPerfectBST ( root . left , k , newTreeSize )
    newK = k - median_loc
    return KSmallestPerfectBST ( root . right , newK , newTreeSize )
