def findKthSmallest ( arr , n , k ) :
    max = 0
    for i in range ( n ) :
        if ( arr [ i ] > max ) :
            max = arr [ i ]
    counter = [ 0 ] * ( max + 1 )
    smallest = 0
    for i in range ( n ) :
        counter [ arr [ i ] ] += 1
    for num in range ( 1 , max + 1 ) :
        if ( counter [ num ] > 0 ) :
            smallest += counter [ num ]
        if ( smallest >= k ) :
